using DesktopNook.Games.Core;
using System.Text.Json;
var checks=new List<object>();
void Assert(bool value,string message){if(!value)throw new Exception(message);}
void Test(string name,Action action){try{action();checks.Add(new{name,passed=true});Console.WriteLine("PASS "+name);}catch(Exception ex){checks.Add(new{name,passed=false,error=ex.ToString()});Console.WriteLine("FAIL "+name+": "+ex.Message);}}
Test("Ball count bounds and independent clone identities",()=>{var r=new BilliardsRound(3,15);Assert(r.Total==15&&r.Balls.Select(b=>b.Id).Distinct().Count()==16&&r.Balls.Skip(1).All(b=>b.Source<3),"clones");foreach(var count in new[]{0,8,46}){try{_ =new BilliardsRound(1,count);throw new Exception("accepted invalid count");}catch(ArgumentOutOfRangeException){}}});
Test("Four rule presets have fixed counts and a separate cue ball",()=>{Assert(BilliardsRules.All.Count==4,"four presets");foreach(var profile in BilliardsRules.All){var r=new BilliardsRound(2,profile.Id);Assert(r.Total==profile.Count&&r.Balls.Count==profile.Count+1&&r.Balls.Skip(1).All(b=>b.Source is 0 or 1),profile.Name);Assert(!BilliardsRules.Matches(profile.Id,45),"free count rejected");}});
Test("Eight ball rack has central black and opposite corner groups",()=>{var r=new BilliardsRound(15,BilliardsRules.Eight);Assert(r.Balls[8].Position==new Vec(1167,450)&&r.Balls[8].Style.Color=="#171D28","black centre");var corners=r.Balls.Where(b=>b.Position.X==1234).OrderBy(b=>b.Position.Y).ToArray();Assert(corners.Length==5&&corners[0].Style.Stripe!=corners[^1].Style.Stripe,"rear groups");Assert(r.Balls.Skip(1).Count(b=>b.Style.Stripe)==7,"seven stripes");});
Test("Nine ball rack is a diamond with one leading and nine central",()=>{var r=new BilliardsRound(9,BilliardsRules.Nine);Assert(r.Balls[1].Position==new Vec(1100,450)&&r.Balls[9].Position==new Vec(1167,450),"one and nine");Assert(r.Balls.Skip(1).GroupBy(b=>b.Position.X).OrderBy(g=>g.Key).Select(g=>g.Count()).SequenceEqual(new[]{1,2,3,2,1}),"diamond");});
Test("Snooker has fifteen reds and six correctly coloured spotted balls",()=>{var r=new BilliardsRound(21,BilliardsRules.Snooker);Assert(r.Total==21&&r.Balls.Skip(1).Count(b=>b.Style.Color=="#D72E35")==15,"reds");Assert(r.Balls.Skip(16).Select(b=>b.Style.Number).SequenceEqual(new[]{2,3,4,5,6,7}),"six colours");Assert(r.Balls[19].Position==new Vec(800,450)&&r.Balls[21].Position==new Vec(1430,450),"blue and black");foreach(var a in r.Balls)foreach(var b in r.Balls.Where(b=>b.Id>a.Id))Assert((a.Position-b.Position).Length>=a.Radius+b.Radius,"no initial overlap");});
Test("Fifteen ball rack numbers and restart preserve rule",()=>{var r=new BilliardsRound(3,BilliardsRules.Fifteen);Assert(r.Balls.Skip(1).Select(b=>b.Style.Number).SequenceEqual(Enumerable.Range(1,15)),"numbers");r.Shoot(new(1100,450),1);r.Advance(.05);r.Reset(2,BilliardsRules.Fifteen);Assert(r.RuleId==BilliardsRules.Fifteen&&r.Total==15&&r.Shots==0,"reset rule");});
Test("No time elapses before first shot",()=>{var r=new BilliardsRound(1,15);r.Advance(10);Assert(r.Elapsed==0&&r.Phase==RoundPhase.Ready&&!r.NeedsFrames,"idle");});
Test("Pause freezes physics and excludes paused time",()=>{var r=new BilliardsRound(1,15);r.Shoot(new(1100,450),1);r.Advance(.04);var p=r.White.Position;double t=r.Elapsed;r.SetPaused(true);r.Advance(10);Assert(r.White.Position==p&&r.Elapsed==t&&!r.NeedsFrames,"pause");r.SetPaused(false);r.Advance(.05);Assert(r.Elapsed>t,"resume");});
Test("Charge cancellation and invalid input never fires",()=>{var r=new BilliardsRound(1,15);r.BeginCharge();r.SetPaused(true);Assert(r.Phase==RoundPhase.Ready&&!r.Shoot(new(1,1),1),"paused charge");r.SetPaused(false);Assert(!r.Shoot(new(double.NaN,1),1)&&!r.Shoot(new(1,1),double.NaN)&&r.Shots==0,"invalid");});
Test("Frontal collision transfers velocity",()=>{Ball a=new Ball{Position=new(100,100),Velocity=new(100,0)},b=new Ball{Position=new(135,100)};BilliardsRound.Collide(a,b);Assert(b.Velocity.X>90&&a.Velocity.X<10&&(b.Position-a.Position).Length>=38-.001,"transfer");});
Test("Separating bodies do not receive extra impulse",()=>{Ball a=new Ball{Position=new(100,100),Velocity=new(-20,0)},b=new Ball{Position=new(130,100),Velocity=new(20,0)};BilliardsRound.Collide(a,b);Assert(a.Velocity.X==-20&&b.Velocity.X==20,"separating");});
Test("Coincident centres stay finite",()=>{Ball a=new Ball{Position=new(100,100)},b=new Ball{Position=new(100,100)};BilliardsRound.Collide(a,b);Assert(double.IsFinite(a.Position.X)&&(a.Position-b.Position).Length>37.9,"finite");});
Test("Aim preview uses expanded collision radius and first obstacle",()=>{var r=new BilliardsRound(1,15);foreach(var b in r.Balls.Skip(1))b.Sunk=true;r.Balls[1].Sunk=false;r.Balls[1].Position=new(800,450);var p=r.Preview(new(1200,450));Assert(p.BallId==1&&Math.Abs(p.Contact.X-763)<.1&&p.ObjectDirection!.Value.X>.99,"preview");});
Test("Wall preview reflects direction",()=>{var r=new BilliardsRound(1,15);foreach(var b in r.Balls.Skip(1))b.Sunk=true;var p=r.Preview(new(420,-100));Assert(p.BallId is null&&p.WhiteDirection!.Value.Y>0,"reflection");});
Test("Shot gating, clock and friction settle deterministically",()=>{var r=new BilliardsRound(1,15);r.Shoot(new(420,200),.18);Assert(!r.Shoot(new(1,1),1),"double shot");for(int n=0;n<4000&&r.Phase is RoundPhase.Stroke or RoundPhase.Rolling;n++)r.Advance(1d/240);Assert(r.Phase is RoundPhase.Ready or RoundPhase.WhitePlacement&&r.Shots==1&&r.Elapsed>0,"settle");});
Test("White pocket does not count as an icon and respawns safely",()=>{var r=new BilliardsRound(1,15);r.Shoot(new(80,80),.2);r.Advance(.05);r.Advance(.05);foreach(var b in r.Balls)b.Velocity=new();r.White.Position=new(80,80);r.Advance(.02);Assert(r.Pocketed==0&&!r.White.Sunk&&r.Phase==RoundPhase.Ready,"white return");});
Test("Pocketing all icons finishes and freezes score time",()=>{var r=new BilliardsRound(1,15);r.Shoot(new(1200,450),.2);foreach(var b in r.Balls.Skip(1))b.Sunk=true;r.Advance(.05);r.Advance(.05);Assert(r.Phase==RoundPhase.Finished&&r.Pocketed==15,"finish");double t=r.Elapsed;r.Advance(1);Assert(r.Elapsed==t,"frozen");});
Test("Restart resets complete round state",()=>{var r=new BilliardsRound(1,15);r.Shoot(new(1200,450),1);r.Advance(.05);r.SetPaused(true);int id=r.RoundNumber;r.Reset(2,45);Assert(r.RoundNumber==id+1&&r.Total==45&&r.Shots==0&&!r.Paused&&r.Elapsed==0&&r.Balls.All(b=>!b.Sunk),"reset");});
Test("High-speed play remains bounded and finite",()=>{var r=new BilliardsRound(45,45);for(int shot=0;shot<8;shot++){r.Shoot(new(1250,300+shot*40),1);for(int n=0;n<2400&&r.Phase is RoundPhase.Stroke or RoundPhase.Rolling;n++)r.Advance(1d/120);}Assert(r.Balls.Where(b=>!b.Sunk).All(b=>double.IsFinite(b.Position.X)&&b.Position.X>=BilliardsRound.Left&&b.Position.X<=BilliardsRound.Right&&b.Position.Y>=BilliardsRound.Top&&b.Position.Y<=BilliardsRound.Bottom),"bounds");});
Test("Pocket tray records targets in order and excludes the white",()=>{var r=new BilliardsRound(2,BilliardsRules.Eight);r.Shoot(new(1200,450),.2);r.Advance(.05);r.Advance(.05);foreach(var b in r.Balls)b.Velocity=new();r.Balls[1].Position=r.Pockets[0];r.Balls[2].Position=r.Pockets[1];r.White.Position=r.Pockets[2];r.Advance(.02);Assert(r.PocketOrder.SequenceEqual(new[]{1,2})&&r.Pocketed==2,"ordered tray");r.Reset(2,BilliardsRules.Eight);Assert(r.PocketOrder.Count==0,"restart clears tray");});
Test("Cue sound occurs at actual strike and preserves shot strength",()=>{foreach(double power in new[]{.2,1d}){var r=new BilliardsRound(1,15);var sounds=new List<BallSound>();r.Sound=sounds.Add;r.BeginCharge();r.CancelCharge();Assert(sounds.Count==0,"cancel silent");r.Shoot(new(1200,450),power);r.Advance(.05);Assert(sounds.Count==0,"not before strike");r.Advance(.05);Assert(sounds.Count(s=>s.Kind==BallSoundKind.Cue)==1&&Math.Abs(sounds.First(s=>s.Kind==BallSoundKind.Cue).Strength-power)<.001,"force event");}});
Test("Recorded hit audio grows with force and stays bounded",()=>{var quiet=BilliardsAudio.Samples(new(BallSoundKind.Cue,.2));var loud=BilliardsAudio.Samples(new(BallSoundKind.Cue,1));double Rms(short[] a)=>Math.Sqrt(a.Average(v=>(double)v*v));Assert(Rms(loud)>Rms(quiet)*2&&loud.Length>quiet.Length&&loud.Max(v=>Math.Abs((int)v))<short.MaxValue,"strength envelope");Assert(BilliardsAudio.Samples(new(BallSoundKind.Cue,double.NaN)).Length>0,"finite fallback");});
Test("Eight ball assigns groups and retains a legal pot turn",()=>{var r=new BilliardsRound(1,BilliardsRules.Eight,2);r.Balls[1].Sunk=true;var result=r.Match.Resolve(r.Balls,1,[1],false);Assert(r.Match.Groups.SequenceEqual(new[]{1,2})&&r.Match.Scores[0]==1&&r.Match.CurrentPlayer==0&&!result.FreeBall,"group and turn");r.Match.Begin(r.Balls);result=r.Match.Resolve(r.Balls,9,[],true);Assert(result.FreeBall&&r.Match.CurrentPlayer==1,"wrong group foul");});
Test("Early black and scratching on black lose eight ball",()=>{foreach(bool scratch in new[]{false,true}){var r=new BilliardsRound(1,BilliardsRules.Eight,2);r.Balls[8].Sunk=true;var result=r.Match.Resolve(r.Balls,8,scratch?[8,0]:[8],true);Assert(result.Finished&&r.Match.Winner==1,"early black loss");}});
Test("Eight ball requires the group cleared before the winning stroke",()=>{var r=new BilliardsRound(1,BilliardsRules.Eight,2);r.Balls[1].Sunk=true;r.Match.Resolve(r.Balls,1,[1],true);foreach(var b in r.Balls.Where(b=>b.Id is >=2 and <=7))b.Sunk=true;r.Match.Begin(r.Balls);r.Balls[8].Sunk=true;var result=r.Match.Resolve(r.Balls,8,[8],true);Assert(result.Finished&&r.Match.Winner==0,"legal black win");});
Test("No-pot legal cushion switches and a dry contact-free stroke fouls",()=>{var r=new BilliardsRound(1,BilliardsRules.Nine,2);var result=r.Match.Resolve(r.Balls,1,[],true);Assert(!result.FreeBall&&r.Match.CurrentPlayer==1,"legal empty turn");r.Match.Begin(r.Balls);result=r.Match.Resolve(r.Balls,null,[],false);Assert(result.FreeBall&&r.Match.CurrentPlayer==0,"no contact foul");});
Test("Nine ball combinations win only after the lowest first contact",()=>{foreach(int first in new[]{1,2}){var r=new BilliardsRound(1,BilliardsRules.Nine,2);r.Balls[9].Sunk=true;var result=r.Match.Resolve(r.Balls,first,[9],true);Assert(first==1?result.Finished&&r.Match.Winner==0:!result.Finished&&result.Respot.Contains(9)&&result.FreeBall,"nine decision");}});
Test("Fifteen ball credits ball values and requires 61 points",()=>{var r=new BilliardsRound(1,BilliardsRules.Fifteen,2);int[] pots=[1,11,12,13,14,15];foreach(int id in pots)r.Balls[id].Sunk=true;var result=r.Match.Resolve(r.Balls,1,pots,true);Assert(r.Match.Scores[0]==66&&r.Match.Winner==0&&result.Finished,"sixty one");});
Test("Fifteen ball foul respots without awarding points",()=>{var r=new BilliardsRound(1,BilliardsRules.Fifteen,2);r.Balls[15].Sunk=true;var result=r.Match.Resolve(r.Balls,2,[15,0],true);Assert(result.Respot.SequenceEqual(new[]{15})&&result.FreeBall&&r.Match.Scores[0]==0&&r.Match.CurrentPlayer==1,"foul respot");});
Test("Snooker alternates reds and colours with colour respot",()=>{var r=new BilliardsRound(1,BilliardsRules.Snooker,2);r.Balls[1].Sunk=true;r.Match.Resolve(r.Balls,1,[1],false);r.Match.Begin(r.Balls);Assert(r.Match.Target.Contains("彩"),"colour target");r.Balls[21].Sunk=true;var result=r.Match.Resolve(r.Balls,21,[21],false);Assert(r.Match.Scores[0]==8&&result.Respot.Contains(21)&&r.Match.CurrentPlayer==0,"black seven points");r.Balls[21].Sunk=false;r.Match.Begin(r.Balls);Assert(r.Match.Target=="红球","back to red");});
Test("Snooker foul awards the opponent four to seven and switches",()=>{var r=new BilliardsRound(1,BilliardsRules.Snooker,2);r.Balls[21].Sunk=true;var result=r.Match.Resolve(r.Balls,21,[21,0],false);Assert(r.Match.Scores[1]==7&&r.Match.Scores[0]==0&&r.Match.CurrentPlayer==1&&result.Respot.Contains(21),"seven point foul");});
Test("Snooker clears colours in order after the final red-colour pair",()=>{var r=new BilliardsRound(1,BilliardsRules.Snooker,2);for(int n=1;n<15;n++)r.Balls[n].Sunk=true;r.Match.Begin(r.Balls);r.Balls[15].Sunk=true;r.Match.Resolve(r.Balls,15,[15],false);r.Match.Begin(r.Balls);r.Balls[21].Sunk=true;var colour=r.Match.Resolve(r.Balls,21,[21],false);Assert(colour.Respot.Contains(21),"last colour respots");r.Balls[21].Sunk=false;for(int id=16;id<=21;id++){r.Match.Begin(r.Balls);r.Balls[id].Sunk=true;r.Match.Resolve(r.Balls,id,[id],false);}Assert(r.Match.Finished&&r.Match.Winner==0&&r.Match.Scores[0]==35,"clear yellow to black");});
Test("Physics settles a dual foul into manual free-ball placement",()=>{var r=new BilliardsRound(1,BilliardsRules.Nine,2);r.Shoot(new(420,100),.18);for(int n=0;n<2000&&r.Phase is RoundPhase.Stroke or RoundPhase.Rolling;n++)r.Advance(1d/120);Assert(r.Match.CurrentPlayer==1&&r.Phase==RoundPhase.WhitePlacement&&r.White.Sunk,"free ball after miss");Assert(r.PlaceWhite(new(420,450))&&r.Phase==RoundPhase.Ready,"place to continue");});
Test("Match restart restores both players and clears progress",()=>{var r=new BilliardsRound(1,BilliardsRules.Nine,2);r.Balls[1].Sunk=true;r.Match.Resolve(r.Balls,1,[1],true);r.Reset(1,BilliardsRules.Nine,2);Assert(r.Match.Players==2&&r.Match.CurrentPlayer==0&&r.Match.Scores.All(s=>s==0)&&!r.Match.Finished&&r.PocketOrder.Count==0,"reset duel");});
Test("Snooker final colour foul uses the ball-on penalty",()=>{var r=new BilliardsRound(1,BilliardsRules.Snooker,2);for(int n=1;n<=15;n++)r.Balls[n].Sunk=true;for(int id=16;id<=20;id++){r.Match.Begin(r.Balls);r.Balls[id].Sunk=true;r.Match.Resolve(r.Balls,id,[id],false);}r.Match.Begin(r.Balls);r.Match.Resolve(r.Balls,null,[],false);Assert(r.Match.Scores[1]==7,"black ball-on penalty");});
Test("Illegal nine is safely respotted and removed from the tray",()=>{var r=new BilliardsRound(1,BilliardsRules.Nine,2);r.Shoot(new(1200,450),.2);r.Advance(.05);r.Advance(.05);foreach(var b in r.Balls)b.Velocity=new();r.Balls[9].Position=r.Pockets[0];r.Advance(.02);Assert(!r.Balls[9].Sunk&&!r.PocketOrder.Contains(9)&&r.Match.CurrentPlayer==1&&r.Phase==RoundPhase.WhitePlacement,"respot and free ball");Assert(r.Balls.All(b=>b.Id==9||b.Sunk||(b.Position-r.Balls[9].Position).Length>=b.Radius+r.Balls[9].Radius),"safe respot");});
Test("Recorded audio preserves waveform timing and supplies all effect kinds",()=>{var a=BilliardsAudio.Samples(new(BallSoundKind.Cue,.2));var b=BilliardsAudio.Samples(new(BallSoundKind.Cue,.35));Assert(a.Length==b.Length&&a.Length>5000,"unshifted recorded soft take");double xy=0,xx=0,yy=0;for(int n=0;n<a.Length;n++){xy+=(double)a[n]*b[n];xx+=(double)a[n]*a[n];yy+=(double)b[n]*b[n];}Assert(xy/Math.Sqrt(xx*yy)>.9999,"amplitude scaling preserves timbre");foreach(var kind in Enum.GetValues<BallSoundKind>())for(int variant=0;variant<2;variant++){var clip=BilliardsAudio.Samples(new(kind,.7),variant);Assert(clip.Length is >5000 and <12000&&clip.Any(v=>v!=0),"recording resource");}});
int failed=checks.Count(c=>JsonSerializer.Serialize(c).Contains("\"passed\":false"));var output=args.FirstOrDefault()??"game-core.json";Directory.CreateDirectory(Path.GetDirectoryName(Path.GetFullPath(output))!);File.WriteAllText(output,JsonSerializer.Serialize(new{passed=checks.Count-failed,failed,checks},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"{checks.Count-failed} passed, {failed} failed");Environment.ExitCode=failed>0?1:0;
